package com.gameaggregator.apikeyservice.application;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.apikeyservice.api.ApiKeyDtos.*;import com.gameaggregator.apikeyservice.domain.ApiKey;import com.gameaggregator.apikeyservice.infrastructure.*;import java.security.SecureRandom;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class ApiKeyService{final ApiKeyRepository repo;final ApiKeyHasher hasher;final ApiKeyCache cache;final ObjectMapper json;final SecureRandom random=new SecureRandom();public ApiKeyService(ApiKeyRepository r,ApiKeyHasher h,ApiKeyCache c,ObjectMapper j){repo=r;hasher=h;cache=c;json=j;}public Issued create(Create r){validateExpiry(r.expiresAt());var generated=generate();var key=new ApiKey(r.tenantId(),r.clientId(),r.environmentId(),hasher.hash(generated.raw),generated.prefix,generated.lastFour,write(r.scopes()),write(r.ipAllowlist()==null?Set.of():r.ipAllowlist()),r.quota(),r.expiresAt());repo.save(key);cache.put(key);return issued(key,generated.raw);}public List<View> list(UUID clientId){return (clientId==null?repo.findAll():repo.findAllByClientId(clientId)).stream().map(this::view).toList();}public View get(UUID id){return view(entity(id));}public Issued rotate(UUID id){var key=entity(id);if("REVOKED".equals(key.status))throw new IllegalStateException("Revoked API key cannot be rotated");String oldHash=key.keyHash;var g=generate();key.keyHash=hasher.hash(g.raw);key.keyPrefix=g.prefix;key.lastFour=g.lastFour;key.rotatedAt=Instant.now();repo.save(key);cache.remove(oldHash);cache.put(key);return issued(key,g.raw);}public View revoke(UUID id){var k=entity(id);k.status="REVOKED";k.revokedAt=Instant.now();cache.remove(k.keyHash);return view(k);}public void delete(UUID id){var k=entity(id);cache.remove(k.keyHash);repo.delete(k);}public Verification verify(String raw){if(raw==null||raw.isBlank())return invalid("MISSING_KEY");var found=repo.findByKeyHash(hasher.hash(raw));if(found.isEmpty())return invalid("INVALID_KEY");var k=found.get();if(!"ACTIVE".equals(k.status))return invalid("REVOKED_KEY");if(k.expiresAt!=null&&!k.expiresAt.isAfter(Instant.now()))return invalid("EXPIRED_KEY");cache.put(k);return new Verification(true,k.tenantId,k.clientId,k.environmentId,read(k.scopesJson),k.quota,"ACTIVE");}private ApiKey entity(UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("API_KEY_NOT_FOUND","API key was not found"));}private record Generated(String raw,String prefix,String lastFour){}private Generated generate(){byte[] p=new byte[6],s=new byte[32];random.nextBytes(p);random.nextBytes(s);String prefix=Base64.getUrlEncoder().withoutPadding().encodeToString(p);String secret=Base64.getUrlEncoder().withoutPadding().encodeToString(s);String raw="gak_live_"+prefix+"_"+secret;return new Generated(raw,prefix,secret.substring(secret.length()-4));}private Issued issued(ApiKey k,String raw){return new Issued(k.id,raw,k.keyPrefix,k.lastFour,k.expiresAt);}private View view(ApiKey k){return new View(k.id,k.tenantId,k.clientId,k.environmentId,k.keyPrefix,k.lastFour,read(k.scopesJson),read(k.ipAllowlistJson),k.quota,k.status,k.expiresAt,k.revokedAt);}private String write(Set<String>s){try{return json.writeValueAsString(s);}catch(Exception e){throw new IllegalArgumentException("Invalid API key metadata",e);}}private Set<String> read(String s){try{return json.readValue(s,new TypeReference<Set<String>>(){});}catch(Exception e){throw new IllegalStateException(e);}}private Verification invalid(String r){return new Verification(false,null,null,null,Set.of(),0,r);}private void validateExpiry(Instant x){if(x!=null&&!x.isAfter(Instant.now()))throw new IllegalArgumentException("Expiration must be in the future");}}